import React from 'react';
import { useParams } from 'react-router-dom';
import { CommunityView as WorkspaceCommunityView } from '../components/workspace/CommunityView';

export const CommunityView = () => {
  const { id } = useParams<{ id: string }>();

  if (!id) {
    return (
      <main className="grid min-h-[100dvh] place-items-center bg-[#0A0A0A] px-6 text-center text-white">
        <div>
          <h1 className="text-2xl font-black">Community not selected</h1>
          <p className="mt-2 text-sm text-white/40">Open a community from your Wersee workspace.</p>
        </div>
      </main>
    );
  }

  return (
    <main className="h-[100dvh] min-h-0 overflow-hidden bg-[#0A0A0A]">
      <WorkspaceCommunityView communityId={id} />
    </main>
  );
};
